package com.example.uniride.backend.model;

import jakarta.persistence.Column;
import jakarta.persistence.Embedded;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/**
 * Registered student. The id is generated by the server (docs/API.md §1). Never returned
 * by a controller: it is mapped to a DTO.
 */
@Entity
@Table(name = "users")
public class User {

    @Id
    private UUID id;

    @Column(nullable = false, unique = true, length = 120)
    private String email;

    @Column(name = "password_hash", nullable = false, length = 100)
    private String passwordHash;

    @Embedded
    private UserProfile profile;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private AccountStatus status;

    /** {@code null} while nobody rated the user. */
    @Column(name = "rating_avg")
    private Double ratingAvg;

    @Column(name = "rating_count", nullable = false)
    private int ratingCount;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    protected User() {
    }

    /** New account, {@code PENDIENTE} until activated (RF01). */
    public User(String email, String passwordHash, UserProfile profile, Instant now) {
        this.id = UUID.randomUUID();
        this.email = Objects.requireNonNull(email);
        this.passwordHash = Objects.requireNonNull(passwordHash);
        this.profile = Objects.requireNonNull(profile);
        this.status = AccountStatus.PENDIENTE;
        this.ratingCount = 0;
        this.createdAt = now;
        this.updatedAt = now;
    }

    public void activate(Instant now) {
        if (status != AccountStatus.ACTIVA) {
            status = AccountStatus.ACTIVA;
            updatedAt = now;
        }
    }

    public void updateProfile(UserProfile newProfile, Instant now) {
        profile = Objects.requireNonNull(newProfile);
        updatedAt = now;
    }

    public void changePassword(String newPasswordHash, Instant now) {
        passwordHash = Objects.requireNonNull(newPasswordHash);
        updatedAt = now;
    }

    public boolean isActive() {
        return status == AccountStatus.ACTIVA;
    }

    public boolean hasVehicle() {
        return profile.getVehicle() != null;
    }

    public UUID getId() {
        return id;
    }

    public String getEmail() {
        return email;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public UserProfile getProfile() {
        return profile;
    }

    public String getFullName() {
        return profile.getFullName();
    }

    public String getPhone() {
        return profile.getPhone();
    }

    public Vehicle getVehicle() {
        return profile.getVehicle();
    }

    public AccountStatus getStatus() {
        return status;
    }

    public Double getRatingAvg() {
        return ratingAvg;
    }

    public int getRatingCount() {
        return ratingCount;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }
}
